import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { motion, useReducedMotion } from 'framer-motion';
import { FiArrowUpRight, FiArrowRight, FiActivity, FiSearch, FiLayers, FiCopy, FiCheck, FiRotateCcw, FiChevronRight, FiChevronDown, FiDownload, FiPlus } from 'react-icons/fi';
import Seo from '../components/Seo';
import Art from '../components/Art';
import './Stream.css';

const samples = [
  { id: 'motor', title: 'Motor sample', source: 'A motor test bench', description: 'A reading becomes an event with the device, test session, and values kept together.', event: 'motor.sample', device_id: 'motor-003', session_id: 'test-run-817', properties: { temperature: 72.4, rpm: 1840, state: 'running' } },
  { id: 'test', title: 'Test verdict', source: 'An automated test', description: 'Your test runner supplies the verdict and the context needed to investigate it later.', event: 'test.completed', device_id: 'ecu-012', session_id: 'validation-042', properties: { test: 'startup_sequence', verdict: 'passed', duration_ms: 842 } },
  { id: 'limit', title: 'Temperature limit', source: 'A monitoring script', description: 'Your script detects a threshold crossing and records the reading alongside its configured limit.', event: 'temperature.limit_exceeded', device_id: 'chamber-02', session_id: 'thermal-cycle-09', properties: { temperature: 86.2, limit: 85, unit: '°C' } },
];
const payloadFor = ({ event, device_id, session_id, properties }) => ({ event, device_id, session_id, properties });
const Arrow = () => <FiArrowUpRight aria-hidden="true" />;

function StreamActions({ className = '' }) {
  return <div className={`sl-goal-actions ${className}`}>
    <Link className="design-button" to="/stream/demo">Try the demo <Arrow /></Link>
    <Link className="design-button secondary" to="/stream/workspace">Open workspace <FiArrowRight aria-hidden="true" /></Link>
  </div>;
}

function EventPreview() {
  const [selected, setSelected] = useState('motor');
  const [mode, setMode] = useState('details');
  const [replay, setReplay] = useState(0);
  const [copied, setCopied] = useState('');
  const reduced = useReducedMotion();
  const sample = samples.find(item => item.id === selected);
  const payload = JSON.stringify(payloadFor(sample), null, 2);
  const selectSample = (id) => { setSelected(id); setCopied(''); };
  const copy = async () => {
    try { await navigator.clipboard.writeText(payload); setCopied('Event JSON copied'); }
    catch { setMode('json'); setCopied('Copy unavailable. Select the JSON text to copy it.'); }
  };
  return <section id="stream-preview" className="design-container sl-preview" aria-labelledby="sl-preview-title">
    <div className="sl-section-heading"><h2 id="sl-preview-title">One event. The whole picture.</h2><p>Choose a workflow and see the context that travels with each event.</p></div>
    <div className="sl-scenarios" role="group" aria-label="Choose an event example">{samples.map(item => <button key={item.id} aria-pressed={selected === item.id} aria-controls="sl-sample-scene" onClick={() => selectSample(item.id)}>{item.title}{selected === item.id && <FiCheck aria-hidden="true" />}</button>)}</div>
    <motion.div key={selected} id="sl-sample-scene" className="sl-sample-scene" initial={reduced ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.42, ease: [0.22, 1, 0.36, 1] }}>
      <div className="sl-scene-heading"><div><small>{sample.source}</small><h3>{sample.title}</h3><p>{sample.description}</p></div></div>
      <div className="sl-path-caption"><span>From source to inspection</span><button type="button" onClick={() => setReplay(value => value + 1)}><FiRotateCcw aria-hidden="true" /> Replay event path</button></div>
      <div className="sl-event-path" key={`${selected}-${replay}`} aria-label="Event path: your system, HTTP capture, event inspection">
        <div><FiActivity aria-hidden="true" /><span>Your system<small>Supplies the event</small></span></div><span className="sl-path-connector" aria-hidden="true"><i /></span><div><FiLayers aria-hidden="true" /><span>HTTP capture<small>Preserves its context</small></span></div><span className="sl-path-connector" aria-hidden="true"><i /></span><div><FiSearch aria-hidden="true" /><span>Event inspection<small>Makes it explorable</small></span></div>
      </div>
      <div className="sl-event-panels">
        <section className="sl-inspector" aria-label="Inspect event"><header><span>Event inspector</span><button type="button" onClick={copy} aria-label="Copy event JSON">{copied === 'Event JSON copied' ? <FiCheck aria-hidden="true" /> : <FiCopy aria-hidden="true" />} {copied === 'Event JSON copied' ? 'Copied' : 'Copy JSON'}</button></header>
          <div className="sl-copy-feedback" role="status" aria-live="polite">{copied}</div>
          <div className="sl-inspector-event"><span><FiActivity aria-hidden="true" /></span><div><small>Event name</small><h4>{sample.event}</h4></div></div>
          <div className="sl-inspector-tabs" role="group" aria-label="Event view">{['details', 'json'].map(value => <button key={value} aria-pressed={mode === value} onClick={() => setMode(value)} aria-controls="sl-inspector-content">{value === 'details' ? 'Event details' : 'Raw JSON'}</button>)}</div>
          <motion.div key={mode} id="sl-inspector-content" initial={reduced ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.25 }}>
            {mode === 'json' ? <><pre className="sl-inspector-json" tabIndex={0} aria-label="Event JSON"><code>{payload}</code></pre><div className="sl-integration-link"><Link to="/stream/demo?view=api">Explore API setup <Arrow /></Link></div></> : <div className="sl-inspector-fields"><dl><div><dt>Device</dt><dd>{sample.device_id}</dd></div><div><dt>Session</dt><dd>{sample.session_id}</dd></div></dl><span className="sl-props-label">Event properties</span><dl className="sl-property-list">{Object.entries(sample.properties).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{String(value)}</dd></div>)}</dl></div>}
          </motion.div>
        </section>
        <aside className="sl-preview-next" role="note"><h3>From one event to the bigger picture.</h3><p>Search event history, filter by device or session, and explore dashboards in the full demo.</p><ul><li><FiSearch aria-hidden="true" /> Find the events that matter.</li><li><FiLayers aria-hidden="true" /> Follow context across your systems.</li><li><FiActivity aria-hidden="true" /> Build a view of your event history.</li></ul><StreamActions /></aside>
      </div>
      <div className="sl-selection-status" role="status" aria-live="polite">{sample.title} selected</div>
    </motion.div>
  </section>;
}

const eventRows = [
  ['16:18:02.183', 'motor.sample', [['motor', '2 fields'], ['device_id', 'bench-01']]],
  ['16:16:32.183', 'battery.sample', [['cell', '1 field'], ['device_id', 'bench-02']]],
  ['16:15:02.183', 'ecu.connected', [['protocol', 'CAN FD'], ['bitrate', '500000'], ['device_id', 'bench-01']]],
  ['16:13:32.183', 'test.failed', [['reason', 'CAN timeout'], ['ecu', 'BMS'], ['device_id', 'bench-03']]],
  ['16:12:02.183', 'motor.sample', [['motor', '2 fields'], ['device_id', 'bench-02']]],
];

// The Events screen of a Stream project, drawn in HTML (not interactive).
function EventsScreen() {
  return <figure className="sl-screen" aria-label="The Events screen in a Stream project (illustration)">
    <div className="sl-toolbar" aria-hidden="true">
      <span className="sl-field sl-field-search"><FiSearch /> Search event names and properties...</span>
      <span className="sl-field">Last 24 hours <FiChevronDown /></span>
      <span className="sl-field sl-hide-sm">All devices <FiChevronDown /></span>
      <span className="sl-field sl-hide-sm">All sessions <FiChevronDown /></span>
      <span className="sl-field sl-field-btn sl-hide-sm"><FiPlus /> Filter</span>
      <span className="sl-field sl-field-btn sl-push"><FiDownload /> Export</span>
    </div>
    <div className="sl-table" aria-hidden="true">
      <div className="sl-tr sl-th"><span>Timestamp, UTC</span><span>Event</span><span>Properties</span><span /></div>
      {eventRows.map(([time, name, props], i) => <div className="sl-tr" key={i}>
        <span className="sl-time">{time}<small>16 Nov</small></span>
        <span className="sl-name">{name}</span>
        <span className="sl-chips">{props.map(([k, v]) => <span className="sl-chip" key={k}>{k} <b>{v}</b></span>)}</span>
        <FiChevronRight className="sl-go" />
      </div>)}
    </div>
  </figure>;
}

// Stream is switched on per project: the service switch as it looks in the workspace.
function ServiceSwitch({ name, on }) {
  return <span className={`sl-service${on ? ' is-on' : ''}`}><span>{name}</span><i className="sl-switch" data-on={on ? 'true' : 'false'} /></span>;
}

export default function Stream() {
  return <main className="stream-design sl-page">
    <Seo title="Plotune Stream: Events for Engineering Systems" description="Understand events from your engineering systems in one explorable history. Try the Plotune Stream demo or open your workspace to connect your tools, test benches, and scripts." path="/stream" />
    <section className="design-container sl-hero">
      <div className="sl-hero-copy">
        <h1>Know what happened. Keep the context.</h1>
        <p>Bring events from your tools, test benches, and scripts into one explorable history. Find the moment, follow the device or session, and see the details that matter.</p>
        <StreamActions className="sl-hero-actions" />
        <span className="sl-hero-note">Explore without an account, or connect your own events.</span>
      </div>
      <div className="art-ground sl-art"><Art name="signal-catchers" priority alt="Small creatures catching signals with a net and passing them down a pipeline of events." /></div>
    </section>
    <section className="design-container sl-screen-section" aria-label="Event history">
      <EventsScreen />
      <p className="sl-sources">Works with Python, C/C++, CAPL, MATLAB, ROS 2, <span translate="no">Nexus</span> and HTTP clients. Any system that can send an HTTP request.</p>
    </section>
    <EventPreview />
    <section className="design-container sl-values" aria-labelledby="sl-values-title"><div className="sl-section-heading"><h2 id="sl-values-title">Less searching. More understanding.</h2><p>From a single device to a shared test session, keep the event and its context together.</p></div><div className="sl-value-grid">{[
      ['Find the moment.', 'Search and filter event history to narrow an investigation to the events that matter.'],
      ['Keep the details.', 'Inspect device and session identifiers alongside the properties your application provides.'],
      ['Explore the pattern.', 'Bring event history into dashboards and saved views you can return to.'],
    ].map(([title, text]) => <article key={title}><h3>{title}</h3><p>{text}</p></article>)}</div></section>
    <section className="design-container sl-workspace" aria-labelledby="sl-ws-title">
      <div>
        <h2 id="sl-ws-title">Part of your workspace.</h2>
        <p>Stream is switched on per project, next to <Link to="/rms">RMS</Link>. Create a workspace, add a project, and turn on what the project needs.</p>
        <Link className="sl-textlink" to="/rms">See RMS <FiArrowRight aria-hidden="true" /></Link>
      </div>
      <div className="sl-project" aria-label="A project with Stream and RMS switched on (illustration)">
        <div className="sl-project-row"><strong translate="no">ECU bench</strong><span className="sl-services"><ServiceSwitch name="Stream" on /><ServiceSwitch name="RMS" on /></span></div>
        <div className="sl-project-row"><strong translate="no">Battery rig</strong><span className="sl-services"><ServiceSwitch name="Stream" on /><ServiceSwitch name="RMS" on={false} /></span></div>
      </div>
    </section>
  </main>;
}
